import { defineVisual } from '@lux/visual-sdk';
import { Scene, Mesh, PlaneGeometry, MeshBasicNodeMaterial, OrthographicCamera } from 'three/webgpu';
import { uniform, vec4 } from 'three/tsl';

export default defineVisual({
  controls: {
    brightness: { type: 'number', label: 'Brightness', default: 0.5, min: 0, max: 1, step: 0.01 },
    speed: { type: 'number', label: 'Speed', default: 0.35, min: -2, max: 2, step: 0.01, unit: 'rad/s' },
    visible: { type: 'boolean', label: 'Visible', default: true },
    palette: {
      type: 'enum', label: 'Palette', default: 'cool', presentation: 'segmented',
      options: [{ id: 'cool', label: 'Cool' }, { id: 'warm', label: 'Warm' }],
    },
  },
  async create(context) {
    const level = uniform(0.5);
    const blue = uniform(0.8);
    const material = new MeshBasicNodeMaterial();
    material.fragmentNode = vec4(level, 0.2, blue, 1);
    const geometry = new PlaneGeometry(1.4, 1.4);
    const scene = new Scene();
    const shape = new Mesh(geometry, material);
    scene.add(shape);
    const camera = new OrthographicCamera(-1, 1, 1, -1, 0, 1);
    return {
      update(frame) {
        level.value = frame.controls.brightness;
        blue.value = frame.controls.palette === 'cool' ? 0.8 : 0.1;
        shape.visible = frame.controls.visible;
        shape.rotation.z += frame.deltaSeconds * frame.controls.speed;
      },
      render(target) { return context.renderer.render(scene, camera, target); },
      reset(_seed) { shape.rotation.z = 0; },
      dispose() { geometry.dispose(); material.dispose(); },
    };
  },
});

